function freshDraft(){return {wizard_step:0,primary:'local',fallbacks:[],dataset_mode:'sample',spec:{name:'My classifier',recipe:'starter',recipe_version:2,steps:500,learning_rate:.05,batch_size:32,epochs:5,seed:42,device:'auto',runtime_minutes:30,free_only:true,paid_cap:0,paid_confirmed:false,trust_script:false,dataset_path:'',script_path:'',label_column:'',output_dir:state.data.settings.output_dir,providers:['local']}};}
function normalizeDraft(raw){const d=raw?.draft??raw,b=freshDraft();if(!d?.spec)return b;const value={...b,...d,spec:{...b.spec,...d.spec}};value.primary=d.primary||d.spec.providers?.[0]||'local';value.dataset_mode=d.dataset_mode||(d.spec.dataset_path?'own':'sample');value.fallbacks=(d.fallbacks||d.spec.providers?.slice(1)||[]).filter(id=>id!==value.primary&&provider(id));value.wizard_step=Math.max(0,Math.min(3,Number(value.wizard_step)||0));Object.assign(value.spec,{free_only:true,paid_cap:0,paid_confirmed:false,trust_script:false});return value;}
