async function initializeWorkspace(){if(state.initialized)return;if(state.initializing)return state.initializing;state.initializing=(async()=>{try{const raw=await api('/api/draft');state.draft=normalizeDraft(raw);state.datasetReport=state.draft.dataset_report||null;const saved=raw.draft||raw;if(saved.spec&&Object.keys(saved.spec).length)state.bootNotice='Draft restored. Paid compute and script permissions need your confirmation again.';}catch{state.draft=freshDraft();state.bootNotice='Your saved draft could not be loaded. This is a new draft.';}if(state.native)state.notifications=Boolean(state.data.settings.desktop_notifications);await route(true);state.initialized=true;})();try{await state.initializing;}finally{state.initializing=null;}}
async function start(){initializeNav();if(!state.native)try{state.notifications=localStorage.getItem('multigpu.notifications')==='on';}catch{}if(!state.pollTimer)state.pollTimer=setInterval(()=>{if(!document.hidden||state.notifications)refresh();},5000);await refresh();}
