/* Setup instructions and progress come from the local controller. Manual confirmations are not provider observations. */
function setupEndpoint(context){return context==='provider'?`/api/providers/${encodeURIComponent(state.providerId)}/setup`:`/api/jobs/${encodeURIComponent(state.jobId)}/setup`;}
function setupGuide(context){return context==='provider'?state.providerSetup:state.jobSetup;}
function activeSetupStep(guide){return guide?.steps?.find(s=>s.id===guide.progress?.current_step)||guide?.steps?.[0];}
function setupCompleted(guide,step){return Boolean(step.completed||(guide.progress?.completed_steps||[]).includes(step.id));}
function setupCanAdvance(context,readControl=true){const guide=setupGuide(context),step=activeSetupStep(guide);if(!step||step.can_complete===false)return false;if(context==='provider'&&state.providerDirty)return false;const acknowledgement=step.completion==='acknowledgement';return acknowledgement?(setupCompleted(guide,step)||Boolean(readControl&&$(`[data-setup-ack="${context}"]`)?.checked)):Boolean(step.ready||setupCompleted(guide,step));}
function setupActionsView(step,context){return (step.actions||[]).map(a=>{if(a.type==='provider-signin')return state.data.desktop_available?action('provider-signin',a.label||'Start native sign-in',a.provider_id||state.providerId):'';if(a.type==='external')return safeLink(a.url,a.label||'Open provider','button');if(a.type==='environment')return action('environment',a.label||'Prepare provider tools',a.profile);if(a.type==='probe'&&context==='provider')return action('probe',a.label||'Save & check',state.providerId,true);if(['notebook','payload'].includes(a.type))return `<button type="button" class="button ${a.type==='notebook'?'primary':''}" data-action="setup-download" data-kind="${a.type}" data-path="${esc(a.path)}" data-filename="${esc(a.filename|| (a.type==='notebook'?`multigpu-${state.jobId?.slice(0,8)}.ipynb`:'training-payload.zip'))}">${esc(a.label|| (a.type==='notebook'?'Download training notebook':'Download training data (ZIP)'))}</button>`;if(a.type==='import')return action('setup-import',a.label||'Import downloaded results');return '';}).join('');}
function setupGuideView(guide,context){if(!guide)return `<div class="setup-loading"><p>${(context==='provider'?state.providerSetupError:state.jobSetupError)?'The setup guide could not be loaded.':'Loading the setup guide…'}</p>${(context==='provider'?state.providerSetupError:state.jobSetupError)?`${errorBox(context==='provider'?state.providerSetupError:state.jobSetupError)}${action('setup-refresh','Retry setup guide',context)}`:''}</div>`;const steps=guide.steps||[],step=activeSetupStep(guide);if(!step)return errorBox('No setup steps were supplied by the controller.');const index=steps.indexOf(step),completed=steps.filter(s=>setupCompleted(guide,s)).length,done=completed===steps.length,ack=step.completion==='acknowledgement'&&!setupCompleted(guide,step),p=provider(guide.provider_id),hasProbe=context==='provider'&&(step.actions||[]).some(a=>a.type==='probe');return `<div class="setup-progress"><span>${completed} of ${steps.length} steps completed</span><span>Saved on this computer</span></div><div class="setup-layout"><ol class="setup-navigation" aria-label="${context==='provider'?'Provider setup':'Training handoff'} steps">${steps.map((s,i)=>`<li><button type="button" data-action="setup-goto" data-context="${context}" data-step="${esc(s.id)}"  ${s===step?'aria-current="step"':''}><span class="setup-step-number">${setupCompleted(guide,s)?icon('check'):i+1}</span><span>${esc(s.title)}${setupCompleted(guide,s)?'<small>Completed</small>':''}</span></button></li>`).join('')}</ol><div class="setup-step-content"><h3 id="${context}-setup-step-title" tabindex="-1">${esc(step.title)}</h3><p class="setup-description">${esc(step.description)}</p>${step.instructions?.length?`<ol class="setup-instructions">${step.instructions.map(text=>`<li>${esc(text)}</li>`).join('')}</ol>`:''}${context==='provider'&&step.id==='signin'&&state.native&&!(step.actions||[]).some(a=>a.type==='provider-signin')?`<div class="button-row">${action('provider-signin','Start native sign-in',guide.provider_id)}</div>`:''}${(step.commands||[]).map(commandBlock).join('')}${step.links?.length?`<div class="setup-links">${step.links.map(link=>safeLink(link.url,link.label||'Official source')).join('')}</div>`:''}${hasProbe?providerConfigView(p):''}<div class="button-row setup-step-actions">${setupActionsView(step,context)}</div>${(step.actions||[]).some(a=>a.type==='environment')?`<div id="provider-environment-task">${environmentTaskView()}</div>`:''}${hasProbe?providerObservationView(p):''}${ack?`<label class="setup-ack switch-row"><input type="checkbox" data-setup-ack="${context}"><span><strong>${esc(step.acknowledgement_label||'I have completed this step')}</strong><small>This saves your confirmation. Provider access and runtime activity are checked separately where supported.</small></span></label>`:setupCompleted(guide,step)?'<p class="setup-observation">This step is complete. You can revisit the instructions.</p>':step.completion==='automatic'&&step.ready?'<p class="setup-observation">The app checked the requirements for this step.</p>':''}<p class="setup-blocker" id="${context}-setup-blocker">${esc(step.can_complete===false?step.blocking_reason||'':'')}</p><div class="setup-controls"><button type="button" class="button" data-action="setup-back" data-context="${context}" ${index===0?'disabled':''}>Back</button><div class="button-row">${action('setup-refresh','Recheck setup',context)}${done&&index===steps.length-1?context==='provider'?'<button type="button" class="button primary" data-action="close-dialog">Done</button>':'<strong class="setup-finished">Guide complete</strong>':`<button type="button" class="button primary setup-next" data-action="setup-next" data-context="${context}" ${setupCanAdvance(context,false)?'':'disabled'}>${index===steps.length-1?'Finish setup':'Continue'} ${icon('arrow')}</button>`}</div></div></div></div>${context==='provider'?`<details class="setup-limits"><summary>Provider limits and official sources</summary><p>${esc(p.free_summary)}</p><ul>${(p.restrictions||[]).map(r=>`<li>${esc(r)}</li>`).join('')}</ul>${safeLink(p.docs_url,'Official provider documentation')}${p.integration==='automatic'&&p.qualification==='live_account_unqualified'?'<p>Adapter implemented; live account qualification pending. Signing in does not certify training, quota, or billing controls.</p>':''}</details>`:''}`;}
function providerConfigView(p){const id=p.id,c=p.connection||{},config=c.config||{},fields=id==='kaggle'?[['username','Kaggle username','your-kaggle-username']]:id==='modal'?[['workspace','Modal workspace','your-workspace'],['gpu','GPU type','T4'],['native_spend_limit','Your provider spending limit (USD)','0.00']]:id==='lightning'?[['user','Lightning user','Leave blank for an organisation'],['organization','Organisation (instead of user)','Leave blank for a personal user'],['teamspace','Teamspace','your-teamspace'],['studio','Existing Studio name','your-studio'],['machine','Machine','Blank keeps existing compute; e.g. T4'],['native_spend_limit','Your provider spending limit (USD)','0.00']]:[];if(!fields.length)return '';const check=(name,title,help='')=>`<label class="switch-row"><input type="checkbox" name="${name}" ${config[name]?'checked':''}><span><strong>${title}</strong>${help?`<small>${help}</small>`:''}</span></label>`;return `<form id="provider-config" class="probe-fields"><div class="fields-grid">${fields.map(([name,label,placeholder])=>`<div class="field"><label for="config-${name}">${label}</label><input id="config-${name}" name="${name}" placeholder="${esc(placeholder)}" value="${esc(config[name]??'')}" autocomplete="off" ${name==='native_spend_limit'?'type="number" min="0" max="100000" step="0.01"':''}${name==='machine'?'list="machine-options"':''}></div>`).join('')}</div>${id==='lightning'?`<datalist id="machine-options">${(c.machine_options||[]).map(m=>`<option value="${esc(typeof m==='string'?m:m.name)}">`).join('')}</datalist>`:''}${check('allow_custom_scripts','Allow my trusted custom scripts on this provider','Only enable this for an account you control.')}${['modal','lightning'].includes(id)?check('entitlement_confirmed','I checked GPU access in my provider account','This is my confirmation, not an independent entitlement check.')+check('budget_confirmed','I configured the stated spending limit with the provider','MultiGPU records the cap I report; it cannot independently verify or enforce that provider limit.'):''}${id==='lightning'?check('start_studio','Allow this run to start my selected Studio','Starting compute may consume credits or incur charges.')+check('dedicated_studio','Use a dedicated Studio and stop it after this run','This Studio must contain no unrelated work. Stopping it ends its compute session.'):''}<button type="submit" class="hidden">Save & check</button></form>`;}
function providerObservationView(p){const c=p.connection||{},q=c.quota;return `<div class="setup-observed"><h4>Last observed setup</h4><p>${esc(c.detail||'This provider has not been checked.')}</p>${providerRecoveryView(p.id,c.error_code,'provider')}<dl class="review-list"><div><dt>Identity</dt><dd>${esc(c.identity?Object.entries(c.identity).filter(([k])=>!['source','verified'].includes(k)).map(([,v])=>v).join(' / '):'Not verified')}</dd></div><div><dt>Actual compute</dt><dd>${esc(actualCompute(c))}</dd></div><div><dt>Allowance</dt><dd>${q?.remaining_hours!=null?number(q.remaining_hours,2)+' reported GPU hours':'Unknown'}</dd></div><div><dt>Checked</dt><dd>${esc(shortDate(c.checked_at))}</dd></div></dl></div>`;}
function renderProviderSetup(focus=false){const dialog=$('#provider-dialog');dialog.classList.add('setup-dialog');const p=provider(state.providerId);if(!p)return;dialog.innerHTML=`<div class="dialog-header"><div><h2 id="provider-dialog-title">Set up ${esc(p.name)}</h2><p>${esc(state.providerSetup?.description||p.free_summary)}</p></div><button type="button" class="icon-button" data-action="close-dialog" aria-label="Close provider setup">${icon('close')}</button></div><div class="dialog-body"><div id="provider-setup-guide">${setupGuideView(state.providerSetup,'provider')}</div><div id="provider-error" role="alert"></div></div>`;if(focus)$('#provider-setup-step-title')?.focus({preventScroll:true});}
async function openProvider(id){if($('#provider-dialog').open&&state.providerDirty&&!window.confirm('Discard unsaved provider settings?'))return;const revision=++state.providerDialogRevision;state.providerId=id;state.providerSetup=null;state.providerSetupError='';state.providerDirty=false;renderProviderSetup();const dialog=$('#provider-dialog');if(!dialog.open)dialog.showModal();try{const guide=await api(`/api/providers/${encodeURIComponent(id)}/setup`);if(revision!==state.providerDialogRevision||!dialog.open)return;state.providerSetup=guide;renderProviderSetup();}catch(e){if(revision!==state.providerDialogRevision||!dialog.open)return;state.providerSetupError=e.message;renderProviderSetup();}}
function closeProvider(){if(state.providerDirty&&!window.confirm('Discard unsaved provider settings?'))return;state.providerDirty=false;state.providerDialogRevision++;$('#provider-dialog').close();}
async function refreshSetup(context,focus=false){const request=++state.setupRequest[context];const revision=state.routeRevision,dialogRevision=state.providerDialogRevision,id=context==='provider'?state.providerId:state.jobId;const guide=await api(setupEndpoint(context));if(request!==state.setupRequest[context])return;if(context==='provider'){if(dialogRevision!==state.providerDialogRevision||!$('#provider-dialog').open||id!==state.providerId)return;state.providerSetup=guide;state.providerSetupError='';if(!state.providerDirty&&(focus||!$('#provider-dialog').contains(document.activeElement)))renderProviderSetup(focus);else updateSetupFooter('provider');}else{if(revision!==state.routeRevision||id!==state.jobId)return;state.jobSetup=guide;state.jobSetupError='';const el=$('#job-setup-guide');if(el&&(focus||!el.contains(document.activeElement))){el.innerHTML=setupGuideView(guide,'job');if(focus)$('#job-setup-step-title')?.focus({preventScroll:true});}}return guide;}
async function changeSetup(context,actionName,stepId){if(state.setupBusy)return;const guide=setupGuide(context),current=activeSetupStep(guide);if(!current)throw Error('Load the setup guide before continuing.');if(context==='provider'&&state.providerDirty){if(!window.confirm('Discard unsaved provider settings?'))return;state.providerDirty=false;}const acknowledged=Boolean($(`[data-setup-ack="${context}"]`)?.checked||setupCompleted(guide,current));if(actionName==='advance'&&!setupCanAdvance(context))throw Error(current.blocking_reason||'Complete the current setup step before continuing.');const revision=state.routeRevision,dialogRevision=state.providerDialogRevision,id=context==='provider'?state.providerId:state.jobId,request=++state.setupRequest[context];state.setupBusy=true;const buttons=all(`[data-context="${context}"]`).map(el=>[el,el.disabled]);buttons.forEach(([el])=>el.disabled=true);let result;try{result=await api(setupEndpoint(context),{action:actionName,step_id:stepId||current.id,acknowledged,...(guide.revision?{guide_revision:guide.revision}:{})});}finally{state.setupBusy=false;buttons.forEach(([el,disabled])=>{if(el.isConnected)el.disabled=disabled;});}if(request!==state.setupRequest[context])return;if(context==='provider'){if(dialogRevision!==state.providerDialogRevision||id!==state.providerId||!$('#provider-dialog').open)return;state.providerSetup=result;renderProviderSetup(true);}else{if(revision!==state.routeRevision||id!==state.jobId)return;state.jobSetup=result;$('#job-setup-guide').innerHTML=setupGuideView(result,'job');$('#job-setup-step-title')?.focus({preventScroll:true});}}
async function probeProvider(id){const revision=state.providerDialogRevision,form=$('#provider-config'),config={...(provider(id).connection?.config||{})};if(form)for(const input of all('input[name]',form))config[input.name]=input.type==='checkbox'?input.checked:input.name==='native_spend_limit'?Number(input.value):input.value.trim();if(id==='lightning')config.stop_studio_after_run=!!config.dedicated_studio;provider(id).connection=await api(`/api/providers/${id}/probe`,config);if(revision===state.providerDialogRevision&&$('#provider-dialog').open&&state.providerId===id){state.providerDirty=false;await refreshSetup('provider');}const connection=provider(id).connection;toast(connection.ready?'Provider connection checked. Review the observed identity and allowance.':'Provider setup needs attention. Review the check details before training.',!connection.ready);}

function isGuidedJob(j){return Boolean(j&&(j.execution_mode==='guided'||(!j.execution_mode&&j.spec?.guided)||j.status==='awaiting_user'));}
function updateSetupFooter(context){const next=$(`.setup-next[data-context="${context}"]`);if(next)next.disabled=!setupCanAdvance(context);const blocker=$(`#${context}-setup-blocker`);if(blocker)blocker.textContent=context==='provider'&&state.providerDirty?'Save & check your changes before continuing.':(activeSetupStep(setupGuide(context))?.can_complete===false?activeSetupStep(setupGuide(context))?.blocking_reason||'':'');}

function providerRecoveryView(pid,code,context){if(!pid||!code)return '';if(context==='job'&&submissionUnresolved(state.job))code='network';const recovery={missing_dependency:{step:'tools',text:'Prepare the provider tools in this app’s environment, then check the connection again.',label:'Prepare provider tools'},unsupported_cli:{step:'tools',text:'The installed client lacks a required command. Repair the app-managed provider tools before checking again.',label:'Repair provider tools'},auth:{step:'signin',text:'Finish the provider’s native sign-in, then return to Save & check.',label:'Open sign-in steps'},account_mismatch:{step:'verify',text:'Match the expected account in this app with the account selected by the native provider tools.',label:'Review account settings'},permission:{step:'verify',text:'Review the account’s access to the selected resource before checking again.',label:'Review account permissions'},quota:{step:'verify',text:'The provider allowance is unavailable or too small for this session. Review its reported quota before changing training limits.',label:'Review provider allowance'},invalid_resource:{step:'verify',text:'Review the selected project, Studio, or machine in the provider settings.',label:'Review resource settings'}}[code];let text='',control='';if(recovery){text=recovery.text;control=`<button type="button" class="button" data-action="provider-recovery" data-id="${esc(pid)}" data-step="${recovery.step}">${recovery.label}</button>`;}else if(code==='network'){text=context==='provider'?'The connection check could not finish. Retry this read-only check when the provider is reachable.':'Check the existing provider attempt before starting another run.';control=context==='provider'?action('probe','Check connection again',pid):state.job&&allowed(state.job,'reconcile')?jobActionButton('reconcile','Check provider state'):safeLink(provider(pid)?.signup_url,'Open provider account','button');}else return '';return `<div data-error-code="${esc(code)}" style="margin-top:12px"><p class="field-help">${esc(text)}</p><div class="button-row" style="margin-top:10px">${control}</div></div>`;}
async function recoverProviderGuide(pid,step){if(!$('#provider-dialog').open||state.providerId!==pid)await openProvider(pid);if(state.providerId!==pid||!$('#provider-dialog').open||!state.providerSetup)return;const target=state.providerSetup.steps.find(s=>s.id===step)||state.providerSetup.steps.find(s=>s.id==='verify')||state.providerSetup.steps[0];if(target)await changeSetup('provider','goto',target.id);}

function diagnosticsView(){const d=state.diagnostics;return `<section class="settings-section"><div class="settings-label"><h2>Application diagnostics</h2><p>Inspect recent application and provider errors.</p></div><div class="settings-content"><details id="diagnostics-panel" ${state.diagnosticsOpen?'open':''}><summary>View application log</summary><div class="button-row" style="margin-top:15px">${action('diagnostics','Refresh log')}</div><p class="storage-path" id="diagnostics-path">${esc(d.path)}</p><div id="diagnostics-error" role="alert">${errorBox(d.error)}</div><pre class="log-output" id="diagnostics-log" tabindex="0" aria-label="Application diagnostic log" style="margin-top:12px">${esc(d.loaded?d.logs||'No application log entries have been recorded.':'Open this section to load recent diagnostics.')}</pre><p class="settings-note">New provider command details are redacted before storage. Earlier messages that were not recorded cannot be recovered.</p></details></div></section>`;}
async function loadDiagnostics(){const revision=state.routeRevision,request=++state.diagnosticsRequest;const pre=$('#diagnostics-log');if(pre&&!state.diagnostics.loaded)pre.textContent='Loading application diagnostics…';try{const result=await api('/api/diagnostics/logs');if(request!==state.diagnosticsRequest)return;state.diagnostics={logs:Array.isArray(result.logs)?result.logs.join('\n'):String(result.logs||''),path:result.path||'',loaded:true,error:''};}catch(e){if(request!==state.diagnosticsRequest)return;state.diagnostics.error=e.message;}if(revision!==state.routeRevision||state.route!=='settings')return;const log=$('#diagnostics-log'),path=$('#diagnostics-path'),error=$('#diagnostics-error');if(log)log.textContent=state.diagnostics.logs||(state.diagnostics.loaded?'No application log entries have been recorded.':'Application diagnostics could not be loaded.');if(path)path.textContent=state.diagnostics.path;if(error)error.innerHTML=errorBox(state.diagnostics.error);}

function trainingEnvironmentView(spec){if(spec.recipe==='starter')return '<p class="recipe-description" style="margin-top:20px">The tabular starter is ready on CPU. No package installation is needed.</p>';if(spec.recipe==='custom')return '<p class="field-help" style="margin-top:20px">Your script owns its dependencies. Prepare them in the intended runtime before training. <a href="#settings">Review this app’s environment</a>.</p>';const profile=spec.recipe==='image'?'image':spec.device==='cuda'?'cuda':'cpu',missing=spec.recipe==='image'?!state.data.hardware.torchvision_available||!state.data.hardware.pillow_available:!state.data.hardware.torch_available;return `<div class="setup-inline"><p>${missing?'Required packages are missing.':'Review the installed environment if you need to repair it.'}</p><div class="button-row">${action('environment',profile==='image'?'Prepare image dependencies':profile==='cuda'?'Prepare CUDA training':'Prepare CPU training',profile)}${action('hardware','Recheck hardware')}</div><div id="environment-task">${environmentTaskView()}</div></div>`;}

function resolutionView(j){if(!allowed(j,'resolve-submission')||!j.recovery_token)return '';const cleanup=j.provider_id==='lightning'&&['pending','failed'].includes(j.cleanup_status),outcome=cleanup?'stopped':jobField('resolution-outcome','attach');return `<details class="panel panel-pad" id="submission-resolution" style="margin-top:24px"><summary>Resolve this provider attempt</summary><p class="field-help" style="margin-top:12px">${cleanup?'Training was not confirmed, and the dedicated Studio may still be running and billing. Stop that Studio in your Lightning account, then explicitly confirm that the Studio is stopped.':'Inspect the saved execution directly in your provider account. Attach its exact ID, or explicitly confirm that it is stopped or absent.'} This records a resolution and does not restart training.</p>${attemptIdentityView(j)}<div class="button-row" style="margin-top:12px">${safeLink(attemptUrl(j)||provider(j.provider_id)?.signup_url,attemptUrl(j)?'Open saved provider attempt':'Open provider account','button')}</div><form id="resolution-form" data-recovery-token="${esc(j.recovery_token)}" style="margin-top:16px"><div class="field"><label for="resolution-outcome">What did you confirm?</label><select id="resolution-outcome">${cleanup?'':`<option value="attach" ${outcome==='attach'?'selected':''}>I found the existing execution</option>`}<option value="stopped" ${outcome==='stopped'?'selected':''}>The execution is stopped</option>${cleanup?'':`<option value="absent" ${outcome==='absent'?'selected':''}>The execution does not exist</option>`}</select></div><div class="field" style="margin-top:12px"><label for="resolution-execution">Exact provider execution ID</label><input id="resolution-execution" value="${esc(jobField('resolution-execution'))}" ${outcome==='attach'?'required':'disabled'} autocomplete="off"><small>Required only when attaching an existing execution.</small></div><label class="switch-row" id="resolution-confirm-row" ${outcome==='attach'?'hidden':''}><input id="resolution-confirm" type="checkbox" ${outcome==='attach'?'':'required'} ${state.jobFields[state.jobId]?._resolutionToken===j.recovery_token&&jobField('resolution-confirm')?'checked':''}><span><strong>${cleanup?'I checked Lightning and confirm that the dedicated Studio is stopped':'I checked the provider console and confirm the selected stopped or absent state'}</strong><small>This is recorded as my confirmation, not automatic provider verification.</small></span></label><div class="field" style="margin-top:12px"><label for="resolution-note">Recovery note (optional)</label><textarea id="resolution-note" rows="2" maxlength="1000">${esc(jobField('resolution-note'))}</textarea></div><button class="button" type="submit" style="margin-top:14px">Save resolution</button></form></details>`;}
function relocationView(j){if(!allowed(j,'relocate-inputs')||!(j.spec.dataset_path||j.spec.script_path))return '';const input=(id,label,value,purpose,choice)=>`<div class="field" style="margin-top:12px"><label for="${id}">${label}</label><div class="path-control"><input id="${id}" value="${esc(jobField(id,value))}"><button type="button" class="button" data-action="choose-path" data-target="${id}" data-kind="file" data-purpose="${purpose}">File…</button>${choice?`<button type="button" class="button" data-action="choose-path" data-target="${id}" data-kind="folder" data-purpose="${purpose}">Folder…</button>`:''}</div></div>`;return `<details id="input-relocation" class="advanced-options"><summary>Locate moved training inputs</summary><p>The new paths must contain the identical script and data. Content and training fingerprint are verified before paths are updated.</p><form id="relocation-form">${j.spec.dataset_path?input('relocate-dataset','Dataset location',j.spec.dataset_path,'dataset',true):''}${j.spec.script_path?input('relocate-script','Script location',j.spec.script_path,'script',false):''}<button class="button" type="submit" style="margin-top:14px">Verify and update paths</button></form></details>`;}
function syncEnvironmentTasks(tasks){if(!Array.isArray(tasks))return;state.environmentTasks=tasks;const active=tasks.find(t=>['queued','running'].includes(t.status));state.environmentTask=active||tasks.find(t=>t.id===state.environmentTask?.id)||tasks[0]||state.environmentTask;}
function environmentListView(){const selected=state.environmentTask;if(!selected)return '<p class="field-help">No dependency preparation tasks have been recorded.</p>';return environmentTaskView()+state.environmentTasks.filter(t=>t.id!==selected.id).slice(0,4).map(t=>`<details class="advanced-options"><summary>${esc(t.profile)} · ${esc(t.status)} · ${esc(shortDate(t.created_at))}</summary><pre class="log-output">${esc((t.logs||[]).join('\n'))}</pre></details>`).join('');}

function manuallyResolved(j){const r=j?.submission_resolution;return Boolean(j?.spec?.attempt_id&&r?.source==='user_confirmed'&&['stopped','absent'].includes(r.outcome)&&r.attempt_id===j.spec.attempt_id);}
function submissionUnresolved(j){return Boolean((j?.submission_status==='unknown'||j?.provider_id==='lightning'&&j.submission_status==='not_started'&&['pending','failed'].includes(j.cleanup_status))&&!manuallyResolved(j));}
function attemptUrl(j){const h=j.handle||j.submission_intent||{};if(h.dashboard_url)return h.dashboard_url;if(j.provider_id==='kaggle'&&h.kernel)return 'https://www.kaggle.com/code/'+h.kernel;return '';}
function attemptIdentityView(j){const h=j.handle||j.submission_intent||{},identity=h.identity||{},pairs=[['Attempt',j.spec.attempt_id],['Account',Object.entries(identity).filter(([k,v])=>typeof v==='string'&&!['source','provider'].includes(k)).map(([k,v])=>`${k}: ${v}`).join(' / ')],['Execution',h.kernel||h.call_id||h.pid||h.remote_dir]];return `<dl class="review-list" style="margin-top:12px">${pairs.filter(([,v])=>v).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;}

function jobExportStatusView(j){return `${j.export_path?`<p class="storage-path">${esc(j.export_path)}</p>${artifactListView(j)}<div class="artifact-actions">${action('artifacts','Download model files')}${allowed(j,'open-export')?jobActionButton('open-export','Open export folder'):''}</div>`:''}`;}

function localGpuField(spec){const h=state.data.hardware;if(!h.cuda_available||h.gpus?.length<2||spec.recipe==='starter'||spec.device==='cpu')return '';return `<div class="field"><label for="field-gpu_index">GPU on this computer</label><select id="field-gpu_index" name="gpu_index">${h.gpus.map((g,i)=>`<option value="${i}" ${Number(spec.gpu_index||0)===i?'selected':''}>${i}: ${esc(g.name)}</option>`).join('')}</select><small>Uses Torch-visible GPU order. Remote providers choose their own GPU and device index.</small></div>`;}
